-- 1. Buat tabel jika belum ada
CREATE TABLE IF NOT EXISTS alumni_database (
  id bigint generated always as identity primary key,
  angkatan text,
  nama_lengkap text,
  negara text default 'Indonesia',
  provinsi text,
  kota text,
  jenis_pekerjaan text,
  bidang_pekerjaan text,
  nama_perusahaan text,
  jabatan text,
  linkedin_url text,
  instagram_url text,
  email text,
  created_at timestamptz default now()
);

ALTER TABLE alumni_database DISABLE ROW LEVEL SECURITY;

